/**
 * The site's illustrations: flat, still pictures in Duolingo's house style,
 * generated by scripts/draw-art.py into the art folder under public.
 *
 * Every path is written out in full rather than built from the name, because
 * the Apps Script build swaps each one for the picture itself — it serves no
 * files of its own — and it finds them by looking for exactly these strings.
 */

import { el } from './dom.js';
import { withBase } from './site.js';
import { currentTheme } from './theme.js';

const ART = {
  logo: '/assets/art/logo.svg',
  mascot: '/assets/art/mascot.svg',
  es: '/assets/art/es.svg',
  fr: '/assets/art/fr.svg',
  it: '/assets/art/it.svg',
  de: '/assets/art/de.svg',
  nl: '/assets/art/nl.svg',
  pt: '/assets/art/pt.svg',
  // Each country picture again in two halves on the same canvas, for the
  // home page's cards, which build the landmark and then fade the food.
  'es-landmark': '/assets/art/es-landmark.svg',
  'es-food': '/assets/art/es-food.svg',
  'fr-landmark': '/assets/art/fr-landmark.svg',
  'fr-food': '/assets/art/fr-food.svg',
  'it-landmark': '/assets/art/it-landmark.svg',
  'it-food': '/assets/art/it-food.svg',
  'de-landmark': '/assets/art/de-landmark.svg',
  'de-food': '/assets/art/de-food.svg',
  'nl-landmark': '/assets/art/nl-landmark.svg',
  'nl-food': '/assets/art/nl-food.svg',
  'pt-landmark': '/assets/art/pt-landmark.svg',
  'pt-food': '/assets/art/pt-food.svg',
  translator: '/assets/art/translator.svg',
  conjugator: '/assets/art/conjugator.svg',
  dictionary: '/assets/art/dictionary.svg',
  chat: '/assets/art/chat.svg',
  soon: '/assets/art/soon.svg',
};

/**
 * Versions drawn for the dark theme. An <img> cannot take the page's colours,
 * so a picture with page-coloured parts in it — the home picture's speech bubbles,
 * white on the light page — has a second drawing, and the image swaps between
 * the two as the theme changes.
 */
const DARK = {
  mascot: '/assets/art/mascot-dark.svg',
};

const resolve = (path) => (path.startsWith('/') ? withBase(path) : path);

/** A decorative picture. They say nothing the text beside them does not. */
export function art(name, { className = '' } = {}) {
  const pick = () => resolve(DARK[name] && currentTheme() === 'dark' ? DARK[name] : ART[name]);
  const image = el('img', {
    class: className,
    // On GitHub Pages under a prefix the path needs it; on Apps Script the
    // path is already a data URI, and the base there is empty.
    src: pick(),
    alt: '',
    decoding: 'async',
  });

  if (DARK[name]) {
    // Follow the theme while the picture is on the page, and stop listening
    // once it has gone — views are rebuilt often.
    const follow = () => {
      if (!image.isConnected && image.dataset.mounted) {
        window.removeEventListener('themechange', follow);
        return;
      }
      image.src = pick();
    };
    requestAnimationFrame(() => { image.dataset.mounted = '1'; });
    window.addEventListener('themechange', follow);
  }
  return image;
}
